def solve(inputs: dict) -> float:
    X = inputs['initial_value']
    a = inputs['multiplier']
    c = inputs['increment']
    m = inputs['modulus']
    rounds = inputs['rounds']

    for _ in range(rounds):
        X = (a * X + c) % m

    return float(X)

