def solve(inputs: dict) -> float:
    terms = inputs['terms']

    if len(terms) == 0:
        return 1.0

    # Initialize p_{-1} and p_0
    p_prev2 = 1  # p_{-1}
    p_prev1 = terms[0]  # p_0

    if len(terms) == 1:
        return float(p_prev1)

    # Compute subsequent numerators using recurrence
    for i in range(1, len(terms)):
        p_curr = terms[i] * p_prev1 + p_prev2
        p_prev2 = p_prev1
        p_prev1 = p_curr

    return float(p_prev1)

